function rcode(){return['# Bias vs variance as darts at a bullseye. Bias shifts the cluster CENTER','# off target; variance is its SPREAD. Total error = bias^2 + variance.','set.seed(1)','bias <- 1.2; variance <- 0.4; n <- 12     # try bias 0 + variance 1.0, etc.','shots_x <- bias + rnorm(n, 0, sqrt(variance))','shots_y <-        rnorm(n, 0, sqrt(variance))','','plot(shots_x, shots_y, xlim = c(-3, 3), ylim = c(-3, 3), asp = 1,','     pch = 19, col = "firebrick", xlab = "", ylab = "")','symbols(rep(0, 3), rep(0, 3), circles = c(0.6, 1.4, 2.2), inches = FALSE, add = TRUE)','','center <- c(mean(shots_x), mean(shots_y))','bias2  <- sum(center^2)                                   # distance from bullseye','var_   <- mean((shots_x - center[1])^2 + (shots_y - center[2])^2)','c(bias2 = bias2, variance = var_, mse = bias2 + var_)'].join('\n');}
