u.runnable(rcode(),{label:'Bin probabilities and draw the reliability curve in R'});var plot=el.querySelector('.cc-plot'),read=el.querySelector('.cc-read'),slider=el.querySelector('.cc-s'),lEl=el.querySelector('.cc-l');function observed(p){var o=Math.pow(p,skew)/(Math.pow(p,skew)+Math.pow(1-p,skew));return o;}
