function rcode(){return['# A reliability diagram bins predictions, then asks: of the cases I called ~0.7,','# what fraction were actually positive? Calibrated => that fraction is ~0.7.','set.seed(1)','n <- 600; x <- rnorm(n)','p_true <- plogis(1.2 * x)              # the real probability','y <- rbinom(n, 1, p_true)','fit <- glm(y ~ x, family = binomial)','p_hat <- predict(fit, type = "response")','','bins <- cut(p_hat, breaks = seq(0, 1, by = 0.1), include.lowest = TRUE)','cal  <- data.frame(','  predicted = tapply(p_hat, bins, mean),','  observed  = tapply(y,     bins, mean))','cal <- cal[complete.cases(cal), ]','','plot(cal$predicted, cal$observed, type = "b", pch = 19,','     xlim = 0:1, ylim = 0:1, xlab = "predicted", ylab = "observed")','abline(0, 1, lty = 2)                  # perfect calibration','cal'].join('\n');}
