function rcode(){return['# An honest split, then a demonstration of leakage.','set.seed(1)','n  <- 200','df <- data.frame(x = rnorm(n), y = rbinom(n, 1, 0.5))','','idx   <- sample(n, 0.7 * n)        # 70% to train, the rest to test','train <- df[idx, ]; test <- df[-idx, ]','c(train = nrow(train), test = nrow(test))','','# LEAKAGE: a feature secretly built from the answer y','df$leak <- df$y + rnorm(n, 0, 0.01)          # "leak" basically IS y','fit  <- glm(y ~ leak, family = binomial, data = df[idx, ])','pred <- predict(fit, df[-idx, ], type = "response") > 0.5','mean(pred == df$y[-idx])                      # ~1.00 - the tell-tale sign of a leak'].join('\n');}
