function rcode(){return['# Logistic regression models a PROBABILITY with an S-curve, then a threshold','# turns that probability into a class.','x <- c(1, 2, 2.5, 3, 4, 4.5, 5.5, 6, 7, 7.5, 8, 9)','y <- c(0, 0, 0,   0, 0, 1,   0,   1, 1, 1,   1, 1)','fit <- glm(y ~ x, family = binomial)','coef(fit)                                   # intercept and slope (log-odds)','','p <- predict(fit, type = "response")        # fitted probabilities','plot(x, y, pch = 19, ylab = "P(y = 1)")','curve(predict(fit, data.frame(x = x), type = "response"),','      add = TRUE, col = "steelblue", lwd = 2)','table(predicted = as.integer(p >= 0.5), actual = y)   # try 0.3 or 0.7'].join('\n');}
