function rcode(){return['# An ROC curve sweeps EVERY threshold. Build it by hand from scores + labels.','pos <- c(0.92,0.86,0.8,0.74,0.7,0.64,0.6,0.54,0.46,0.4)   # actual positives','neg <- c(0.6,0.5,0.46,0.4,0.34,0.3,0.25,0.2,0.14,0.1)     # actual negatives','score  <- c(pos, neg)','actual <- c(rep(1, length(pos)), rep(0, length(neg)))','','thr <- seq(0, 1, by = 0.02)','roc <- t(sapply(thr, function(t) {','  pred <- score >= t','  c(FPR = sum(pred & actual == 0) / sum(actual == 0),','    TPR = sum(pred & actual == 1) / sum(actual == 1))','}))','plot(roc[, "FPR"], roc[, "TPR"], type = "l", lwd = 2, xlab = "FPR", ylab = "TPR")','abline(0, 1, lty = 2)','','o   <- order(roc[, "FPR"])                       # area under the curve (trapezoid)','auc <- sum(diff(roc[o, "FPR"]) * (head(roc[o, "TPR"], -1) + tail(roc[o, "TPR"], -1)) / 2)','auc'].join('\n');}
