function rcode(){return['# For a linear model, a feature\'s SHAP value has an exact closed form:','#   contribution_j = beta_j * (x_j - mean(x_j))','# and the contributions + the baseline sum to the prediction.','set.seed(1)','d <- data.frame(tenure = rnorm(200), spend = rnorm(200), calls = rnorm(200))','d$y <- 0.3 + 0.8*d$tenure + 0.5*d$spend - 0.6*d$calls + rnorm(200, 0, 0.3)','fit <- lm(y ~ tenure + spend + calls, data = d)','','b   <- coef(fit)[-1]                 # slopes','mu  <- colMeans(d[, c("tenure","spend","calls")])','row <- d[1, c("tenure","spend","calls")]','contrib <- b * (unlist(row) - mu)    # per-feature SHAP contributions','','baseline <- predict(fit, newdata = as.data.frame(t(mu)))','c(baseline = baseline, contrib,','  reconstructed = baseline + sum(contrib),  # == the prediction','  prediction    = predict(fit, newdata = row))'].join('\n');}
